#ifndef _mulle_objc_yaml_foundation_include_h__
#define _mulle_objc_yaml_foundation_include_h__

// To remove the following dependency (headers and library) completely:
//   `mulle-sde dependency remove libyaml`
// (Use 543A362C-725B-463B-8F4A-AFB633C97808 instead of libyaml, if there are duplicate entries)
//
// You can tweak the following #include with these commands:
//    remove #include: `mulle-sde dependency mark libyaml no-header`
//    rename              : `mulle-sde dependency|library set libyaml include whatever.h`
//    reorder             : `mulle-sde dependency move libyaml <up|down>`
//    toggle objc         : `mulle-sde dependency mark libyaml [no-]import`
//    toggle public       : `mulle-sde dependency mark libyaml [no-]public`
//    toggle optional     : `mulle-sde dependency mark libyaml [no-]require`
//    remove for platform : `mulle-sde dependency mark libyaml no-platform-<uname>`
//        (use `mulle-sourcetree-to-c --unames` to list known values)
#include <yaml.h>   // libyaml

#endif
